using Cap7CE.Core.Protocol;
using Cap7CE.WinUI.Models;

var checks=0;
void Require(bool condition,string label){if(!condition)throw new Exception(label);checks++;}
var empty=new BrowseFilter();
var sunday=new DateTime(2026,10,25,23,59,0);
var week=FilterPresets.Time(empty,"week",sunday);
Require(week.After?.Date==new DateTime(2026,10,19)&&week.Before?.Date==new DateTime(2026,10,26),"Sunday stays in the Monday-based week");
var feb=FilterPresets.Time(empty,"month",new DateTime(2028,2,29));
Require(feb.After?.Date==new DateTime(2028,2,1)&&feb.Before?.Date==new DateTime(2028,3,1),"Leap-month calendar boundaries");
var prior=FilterPresets.Time(empty,"last-year",sunday);
Require(prior.After?.Date==new DateTime(2025,1,1)&&prior.Before?.Date==new DateTime(2026,1,1),"Previous calendar year");
Require(week.ToConditions()!.MaximumModifiedFileTime==(week.Before!.Value.UtcDateTime.ToFileTimeUtc()-1).ToString(),"Exclusive UI end becomes inclusive Core FILETIME without next-day leakage");
Require(FilterPresets.Time(week,"all",sunday).Count==0,"Unlimited time removes the condition");
for(var i=0;i<FilterPresets.Sizes.Length-1;i++)Require(FilterPresets.Sizes[i].Max+1==FilterPresets.Sizes[i+1].Min,"Size presets neither overlap nor leave gaps");
var images=FilterPresets.ToggleType(empty,"visual");
Require(FilterPresets.Selected(images,"visual")&&FilterPresets.Domain(images)=="image-dimensions","Image group selects all registered searchable images");
var mixed=FilterPresets.ToggleType(images with {Facts=new CoreSearchFactFilter("image-dimensions",1,MinimumWidth:100)},"audio");
Require(FilterPresets.Selected(mixed,"visual")&&FilterPresets.Selected(mixed,"audio")&&mixed.Facts is null,"Mixed categories combine extensions and remove incompatible facts");
var remaining=FilterPresets.ToggleType(mixed,"visual");
Require(FilterPresets.Selected(remaining,"audio")&&!FilterPresets.Selected(remaining,"visual"),"Removing one category retains the other");
var other=FilterPresets.ToggleType(images,"other");
Require(other.Category=="other"&&other.Extensions.Length==0&&other.ToConditions()!.ExcludedExtensions!.Count>0,"Unclassified selection uses exclusion rather than image includes");
Require(FilterPresets.ToggleType(other,"other").Count==0,"Unclassified selection toggles off");
Require(FormatRegistry.Formats.Select(f=>f.Extension).Distinct().Count()<=128,"Registered formats fit the existing Core condition bound");
var ratio=AspectFilterRules.Around(16,9);
Require(ratio==AspectFilterRules.Around(1920,1080),"Equivalent custom ratios normalize to the same tolerance range");
Require(AspectFilterRules.Label(ratio)=="16:9","Custom ratio label survives normalization");
Require(Math.Abs(ratio.Minimum!.Numerator/(double)ratio.Minimum.Denominator-16d/9*.98)<1e-10,"Custom ratio uses mainline lower tolerance");
Require(Math.Abs(ratio.Maximum!.Numerator/(double)ratio.Maximum.Denominator-16d/9*1.02)<1e-10,"Custom ratio uses mainline upper tolerance");
var visual=new CoreSearchFactFilter("image-dimensions",1,MinimumWidth:1920,IsAnimated:true,AspectRanges:[ratio]);
visual=VisualFilterRules.Toggle(VisualFilterRules.Toggle(VisualFilterRules.Toggle(visual,"red"),"blue"),"bright-image");
Require(visual.VisualGroups is {Count:2}&&visual.VisualGroups[0].Alternatives.Count==2&&visual.VisualGroups[1].Alternatives.Count==1,"Colors form a union; traits form a separate intersection group");
Require(visual.MinimumWidth==1920&&visual.IsAnimated==true&&visual.AspectRanges!.Contains(ratio),"Color changes preserve dimensions, animation and aspect");
Require(VisualFilterRules.Selected(visual,"red")&&!VisualFilterRules.Selected(VisualFilterRules.Toggle(visual,"red"),"red"),"Visual selector toggles off independently");
var noDimensions=AspectFilterRules.ClearDimensions(visual);
Require(noDimensions.MinimumWidth is null&&noDimensions.VisualGroups==visual.VisualGroups&&noDimensions.AspectRanges==visual.AspectRanges,"Clearing dimensions preserves other groups");
var noAspect=AspectFilterRules.ClearAspect(visual);
Require(noAspect.AspectRanges is null&&noAspect.VisualGroups==visual.VisualGroups&&noAspect.MinimumWidth==1920,"Clearing aspect preserves other groups");
Require(FilterFactRules.Count(visual)==4,"Visual conditions count by visible groups");
Require(AspectFilterRules.Normalize(VisualFilterRules.Apply(new("video",1),new HashSet<string>{"transparent-background"})) is null,"Video excludes image transparency semantics");
Require(AspectFilterRules.Normalize(VisualFilterRules.Apply(new("image-dimensions",1),new HashSet<string>())) is null,"Clearing final visual condition removes the facts filter");
Require(VisualFilterRules.Definitions.All(d=>d.Constraints.Length is >0 and <=8&&d.Constraints.All(c=>c.Value is >=0 and <=10000)),"Generated visual semantics fit existing Core constraint bounds");
var largest=AspectFilterRules.Around(99999,100000);
Require(largest.Minimum!.Numerator<=10000000&&largest.Maximum!.Numerator<=10000000&&largest.Maximum.Denominator<=10000000,"Largest custom inputs fit existing Core aspect endpoint bounds");
Console.WriteLine($"Top filter checks passed: {checks}");
